do $$declare x jsonb;begin x:=public.cbgpu_school_direct_messaging_api('preferences');if x->>'allow_direct_messages'<>'false'then raise exception 'DM_DEFAULT_NOT_PRIVATE';end if;begin perform public.cbgpu_school_direct_messaging_api('conversation_create','{"recipient_id":"fb810000-0000-4000-8000-000000000002","scope":"SCHOOL","school_id":"fixture-direct-b"}');raise exception 'DM_WITHOUT_OPTIN';exception when no_data_found then null;end;end$$;
